func init() {
	for _, key := range runtimeCutover {
		for i := range manifest {
			if manifest[i].Key == key {
				manifest[i].Runtime = true
				break
			}
		}
	}
}

func Manifest() []Entry {
	out := make([]Entry, len(manifest))
	for i, e := range manifest {
		e.Choices = slices.Clone(e.Choices)
		out[i] = e
	}
	return out
}

