func RemovedOperatorInputs() []Entry {
	var out []Entry
	for _, key := range slices.Sorted(maps.Keys(removedKeys)) {
		if e := removedKeys[key]; e.Class == ClassOperator && e.Module != "" {
			out = append(out, e)
		}
	}
	return out
}

func RemovedHostKey(key string) (string, bool) {
	entry, ok := removedKeys[key]
	if !ok || entry.Module != "auth" {
		return "", false
	}
	return entry.Target, true
}

func EntryFor(key string) (Entry, bool) {
	for _, e := range manifest {
		if e.Key == key {
			e.Choices = slices.Clone(e.Choices)
			return e, true
		}
	}
	if e, ok := removedKeys[key]; ok {
		return e, true
	}
	return Entry{}, false
}
